test_enumerations_are_classified_parsed[import ast, inspect
def t():
 src = inspect.getsource(M)
 ast.parse(src)
]

test_enumerations_are_classified_parsed[import ast, inspect
def t():
 src = inspect.getsource(M)
 ast.parse(src.replace('a', 'b'))
]

test_text_pins_are_classified_textual[import inspect
def t():
 src = inspect.getsource(M)
 assert 'x' in src
]

test_text_pins_are_classified_textual[import inspect
def t():
 src = inspect.getsource(M)
 i = src.index('x')
]

test_text_pins_are_classified_textual[import inspect
def t():
 src = inspect.getsource(M)
 w = src[10:90]
]

test_text_pins_are_classified_textual[import inspect, re
def t():
 src = inspect.getsource(M)
 re.search('x', src)
]

test_text_pins_are_classified_textual[from pathlib import Path
def t():
 src = Path(M.__file__).read_text()
 assert 'x' in src
]
